create database customer_behavior;

use customer_behavior;

select * from customer limit 20;

#1. total revenue generated by male vs female customers?

select gender, SUM(purchase_amount) as revenue
from customer
group by gender;

 #customer used a discount but still spent more than the average review rating?
 
 select customer_id, purchase_amount
 from customer
 where discount_applied = 'yes' and purchase_amount >= (select avg(purchase_amount) from customer);
 
 #top 5 products with the highest average review rating
 
 select item_purchased, avg(review_rating) as "Average Product Rating"
 from customer
 group by item_purchased
 order by avg(review_rating) desc limit 5;
 
 #compare the average purchase amount between standard and express shipping
 
 select shipping_type,
 avg(purchase_amount)
 from customer
 where shipping_type in ('standard', 'express')
 group by shipping_type;

#Do subscriber customers spend more? Compare average spend and total revenue between subscribers and non-subscribers?

select subscription_status, 
count(customer_id) as total_customers, 
sum(purchase_amount) as total_revenue, 
avg(purchase_amount) as avg_revenue
from customer
group by subscription_status
order by total_revenue, avg_revenue desc;

#5 products have the highest percentage of purchases with discounts applied?

select item_purchased,
round(100 * sum(case when discount_applied = 'yes' then 1 else 0 end)/count(*),2) as discount_rate
from customer
group by item_purchased
order by discount_rate desc
limit 5; 

